import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

public class SecureController {

    public void handleUserInput(HttpServletRequest request, HttpServletResponse response) {
        // Extract parameter and validate it first
        String userInput = request.getParameter("username");

        // Validate input length and content (e.g., allow only letters and numbers)
        if (userInput == null || userInput.trim().isEmpty() || 
            userInput.length() > 50 || !userInput.matches("^[a-zA-Z0-9_]+$")) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.getWriter().write("Invalid username format.");
            return;
        }

        // Use parameterized query to prevent SQL injection
        // The input is treated as data, not executable code
        String query = "SELECT * FROM users WHERE name = ?;";

